/**
 * The identifiers for the user. Options are restricted to the set that is currently supported.
 */

/**
 * Base client options. Does not include any options specific to providers
 * @interface BaseClientOptions
 * @property {FeatureGateEnvironment} environment - The environment for the client.
 * @property {string} targetApp - The target app for the client.
 * @property {AnalyticsWebClient} analyticsWebClient - The analytics web client.
 * @property {PerimeterType} perimeter - The perimeter for the client.
 */

/**
 * The options for the client.
 * @interface ClientOptions
 * @extends {BaseClientOptions}
 * @property {string} apiKey - The API key for the client.
 * @property {fetchTimeoutMs} fetchTimeoutMs - The timeout for the fetch request in milliseconds. Defaults to 5000.
 * @property {boolean} useGatewayURL - Whether to use the gateway URL. Defaults to false.
 * @property {boolean} includeFfpFlags - Whether to include flags served by the Feature Flag Platform. Defaults to false.
 */

// oxlint-disable-next-line eslint/no-redeclare

/**
 * The custom attributes for the user.
 */

// oxlint-disable-next-line eslint/no-redeclare
export var FeatureGateEnvironment = {
  Development: 'development',
  Staging: 'staging',
  Production: 'production'
};
// If adding new values here, please check FeatureGates.getDefaultPerimeter to make sure it still returns something sensible.
// oxlint-disable-next-line eslint/no-redeclare eslint-disable-next-line @atlaskit/volt-strict-mode/no-multiple-exports
export var PerimeterType = {
  COMMERCIAL: 'commercial',
  FEDRAMP_MODERATE: 'fedramp-moderate'
};

/**
 * Feature Flag Platform bootstrap values: the `ffp` member of the Feature Flag Service
 * `/api/v1/evalFlags` response. The service partitions flags, so a key is present here only when FFP
 * (rather than Statsig) serves it. Members other than those of `BulkEvaluationPayloadV1` are
 * ignored; `vs` is forwarded so the FFP client rejects a schema version it does not support.
 * `requestContext` is required: without it the FFP client rejects the values and FFP serves nothing
 * for the user.
 */

/**
 * Health of a provider as reported by the Feature Flag Service `/api/v1/evalFlags` endpoint.
 * - `OK`: evaluated; its section has every flag the provider serves (possibly none).
 * - `DISABLED`: deliberately not used; its section is empty and calling again will not change that.
 * - `UNAVAILABLE`: should have been used but could not be evaluated; its section is empty and calling
 *   again may give a better result.
 */

/** A flag provider behind the Feature Flag Service. */

// eslint-disable-next-line @atlaskit/volt-strict-mode/no-multiple-exports
export var NON_BOOLEAN_VALUE = 'non_boolean';

